// ===== v3.33: nối lại bản đồ (thành ≤3 cổng; bản đồ cao đi từ bản đồ thấp) + nới rộng bản đồ chiến đấu =====
(function relinkWorld(){
  function rm(z,to){ ZONES[z].portals=ZONES[z].portals.filter(p=>p.to!==to); }
  function ren(z,from,to,label,lv){ const p=ZONES[z].portals.find(q=>q.to===from); if(p){ p.to=to; p.label=label; if(lv)p.lv=lv; else delete p.lv; } }
  function add(z,to,x,y,label,lv){ ZONES[z].portals.push({x,y,r:44,to,tx:0,ty:0,label,lv}); }
  rm('town','town2');                                          // An Bình: Rừng Ma · Hang Băng · Mật Thất
  rm('town2','town'); rm('town2','desert'); rm('town2','town3'); // Sương Giá: Hang Băng T2 · Đầm Lầy · Nghĩa Địa
  rm('town3','sanct'); rm('town3','town2');                    // Pháo Đài: Sa Mạc T2 · Tháp · Vực Dung Nham
  // Sa Mạc giờ đi từ Nghĩa Địa Tầng 2; Thánh Địa đi từ Vực Dung Nham Tầng 2
  const g2=ZONES.graveyard2; add('graveyard2','desert',g2.w-60,g2.h/2,'→ Sa Mạc Xương Trắng',70);
  ren('desert','town2','graveyard2','← Nghĩa Địa T2');
  const l2=ZONES.lava2; add('lava2','sanct',l2.w/2,60,'↑ Thánh Địa',130);
  ren('sanct','town3','lava2','↓ Vực Dung Nham T2');
  // nới rộng bản đồ chiến đấu (bãi quái cách xa nhau hơn)
  const F=1.4; for(const z in ZONES){ const Z=ZONES[z]; if(Z.safe)continue; Z.sc=F; Z.w=Math.round(Z.w*F); Z.h=Math.round(Z.h*F);
    for(const p of Z.portals){ p.x=Math.round(p.x*F); p.y=Math.round(p.y*F); } }
  for(const k in BOSS_DEF_RAW){ const b=BOSS_DEF_RAW[k]; if(b.lx&&ZONES[k]&&ZONES[k].sc){ b.lx=Math.round(b.lx*ZONES[k].sc); b.ly=Math.round(b.ly*ZONES[k].sc); } }
  // điểm đáp = cạnh cổng quay về, lùi vào trong bản đồ 90px
  for(const z in ZONES) for(const p of ZONES[z].portals){ const D=ZONES[p.to]; if(!D)continue; const back=D.portals.find(q=>q.to===z);
    if(back){ const cx=D.w/2, cy=D.h/2, dx=cx-back.x, dy=cy-back.y, d=Math.hypot(dx,dy)||1; p.tx=Math.round(back.x+dx/d*95); p.ty=Math.round(back.y+dy/d*95); }
    else { p.tx=Math.round(D.w/2); p.ty=Math.round(D.h/2); } }
})();
const COMBAT_ZONES=Object.keys(ZONES).filter(z=>!ZONES[z].safe);
// ===== DỊCH CHUYỂN (kiểu MU /move) =====
function warpLv(z){ const Z=ZONES[z]; if(!Z)return 999; if(z==='town')return 1; if(z==='town2')return 50; if(z==='town3')return 95; return (Z.lv||1)+10; }
function warpCost(z){ const Z=ZONES[z]; return Z.safe?(z==='town'?50:(z==='town2'?800:3000)):Math.round(60*Math.pow(Z.tier||1,2)); }
function warpList(){ return Object.keys(ZONES).filter(z=>!z.startsWith('dungeon')).map(z=>({id:z,name:ZONES[z].name,lv:warpLv(z),cost:warpCost(z),town:!!ZONES[z].safe})); }
function warpSpot(z){ const Z=ZONES[z]; for(const k in ZONES) for(const p of ZONES[k].portals) if(p.to===z) return {x:p.tx,y:p.ty}; return {x:Z.w/2,y:Z.h/2}; }
function doWarp(p,id,to){ const Z=ZONES[to]; if(!Z||to.startsWith('dungeon'))return; if(p.dead)return;
  if((p.lv||1)<warpLv(to)){ sendTo(id,{t:'toast',text:'⛔ Cần cấp '+warpLv(to)+' để dịch chuyển tới '+Z.name+' (đi bộ vào được từ cấp '+(Z.lv||1)+')'}); return; }
  if(p.hurtT!==undefined&&p.hurtT<4){ sendTo(id,{t:'toast',text:'Đang giao chiến — không thể dịch chuyển.'}); return; }
  if((p.warpCd||0)>Date.now()){ sendTo(id,{t:'toast',text:'Bùa dịch chuyển đang hồi ('+Math.ceil((p.warpCd-Date.now())/1000)+'s).'}); return; }
  const c=warpCost(to); if((p.gold||0)<c){ sendTo(id,{t:'toast',text:'Không đủ '+c+'🪙 để dịch chuyển.'}); return; }
  p.gold-=c; p.warpCd=Date.now()+8000; CURZ=p.zone; fxEv('warpout',p.x,p.y,0,0,0,40); const s=warpSpot(to); p.zone=to; p.x=s.x; p.y=s.y; p._wz=null; p.iframe=Math.max(p.iframe||0,2); CURZ=to; fxEv('warpin',p.x,p.y,0,0,0,40);
  sendTo(id,{t:'toast',text:'✨ Đã dịch chuyển tới '+Z.name+' (−'+c+'🪙)'}); sendInv(p,id); }
function ztier(z){ return (ZONES[z]&&ZONES[z].tier)||1; }
function zoneOf(p){ return ZONES[p.zone]||ZONES.town; }

// ---- THÚ CƯNG (con vật chiến đấu cùng chủ) — săn từ Boss Thế Giới. v3.26: mỗi con 1 VAI TRÒ: chiến đấu / chữa thương / tăng sức mạnh
// (id giữ nguyên để save cũ không lỗi; ĐỆ TỬ giờ là NGƯỜI — xem DISC_TYPES)
const PET_TYPES = [
  {id:'wolf',  name:'Hồ Ly Lửa',   icon:'🦊', hue:20,  role:'Chiến đấu', effect:'lifesteal', desc:'Chiến đấu: cắn liên tục, mỗi đòn hồi máu cho chủ'},
  {id:'scorp', name:'Ếch Độc',     icon:'🐸', hue:110, role:'Chiến đấu', effect:'poison',    desc:'Chiến đấu: phun độc, quái mất máu theo thời gian'},
  {id:'owl',   name:'Sóc Pháp Sư', icon:'🐿️', hue:195, role:'Chữa thương', effect:'heal',    desc:'Chữa thương: cứ 4 giây hồi 6% máu tối đa cho chủ (+ đánh nhẹ)'},
  {id:'dragon',name:'Rồng Con',    icon:'🐲', hue:45,  role:'Tăng sức mạnh', effect:'stungold', desc:'Tăng sức mạnh: chủ +15% sát thương khi rồng theo · đòn đánh có thể choáng + rớt vàng'},
  {id:'bat',   name:'Dơi Máu',      role:'Chiến đấu',     icon:'🦇', hue:330, effect:'bleed',     desc:'Đòn đánh gây chảy máu, chặn hồi máu mục tiêu'},
];
function randPetType(){ return PET_TYPES[Math.floor(Math.random()*PET_TYPES.length)]; }
// v3.29: thú cưng mạnh chỉ có ở boss bản đồ cao: T1-3 Hồ Ly/Ếch · T4-6 +Sóc chữa/Dơi · T7+ Rồng Con tăng lực
function randPetTypeT(zt){ const ids=zt<=3?['wolf','scorp']:(zt<=6?['wolf','scorp','owl','bat']:['owl','bat','dragon']); const L=PET_TYPES.filter(t=>ids.includes(t.id)); return L[Math.floor(Math.random()*L.length)]; }
function petBaseStats(lv){ return { atk: 8+lv*3, hpMul: 1+lv*0.15 }; }
function tickPet(p,id,dt){
  const pet=p.pet;
  if(pet.zone!==p.zone){ pet.zone=p.zone; pet.x=p.x; pet.y=p.y; }
  const tx=p.x-p.fx*36, ty=p.y-p.fy*36;
  pet.x+=(tx-pet.x)*Math.min(1,dt*4); pet.y+=(ty-pet.y)*Math.min(1,dt*4);
  pet.fullness=Math.max(0,(pet.fullness||100)-dt*(100/1800)); // đói dần, hết trong ~30 phút không cho ăn
  pet.atkT=(pet.atkT||0)-dt;
  if(pet.type==='owl'){ pet.healT=(pet.healT===undefined?4:pet.healT)-dt;
    if(pet.healT<=0){ pet.healT=4; if(p.hp<p.maxhp&&!p.dead){ const h=Math.round(p.maxhp*0.06*((pet.fullness>0)?1:0.5)); p.hp=Math.min(p.maxhp,p.hp+h); hitEv(p.x,p.y-24,'+'+h,false); fxEv('bossnova',p.x,p.y,120,0,0,34); } } }
  if(pet.atkT<=0){
    pet.atkT=3.5;
    let best=null,bd=140;
    for(const eid in enemies){const e=enemies[eid];if(e.dead||e.zone!==pet.zone)continue;const d=Math.hypot(e.x-pet.x,e.y-pet.y);if(d<bd){bd=d;best=e;}}
    if(best){
      const eff=(pet.fullness>0)?1:0.5; // đói quá thì giảm hiệu quả, không tắt hẳn
      const dmg=Math.round((pet.atk||8)*eff);
      hurtEnemy(best,dmg,id);
      fxEv('bite',best.x,best.y,0,1,0,0);
      const pt=PET_TYPES.find(t=>t.id===pet.type);
      if(pt.effect==='lifesteal'){ const heal=Math.round(dmg*0.4); p.hp=Math.min(p.maxhp,p.hp+heal); hitEv(p.x,p.y-16,heal,true); }
      else if(pt.effect==='poison'){ const tick=Math.round(dmg*0.3),tgt=best;
        for(let i=1;i<=3;i++) setTimeout(()=>{ if(!tgt.dead) hurtEnemy(tgt,tick,id); }, i*1000); }
      else if(pt.effect==='root'||pt.effect==='heal'){ best.slowT=1.2; best.slowMul=0.5; }
      else if(pt.effect==='stungold' && Math.random()<0.4){ best.slowT=1.5; best.slowMul=0.03; p.gold+=15; bcast({t:'gold',id,x:p.x,y:p.y,val:15,st:0}); }
      else if(pt.effect==='bleed'){ const tick=Math.round(dmg*0.35),tgt2=best;
        for(let i=1;i<=2;i++) setTimeout(()=>{ if(!tgt2.dead) hurtEnemy(tgt2,tick,id); }, i*800); }
    }
  }
}
function tickSummon(p,id,dt){
  const s=p.summon;
  s.expireT-=dt; if(s.expireT<=0){ p.summon=null; sendTo(id,{t:'toast',text:'Cấm Vệ Quân đã hết hạn triệu hồi.'}); return; }
  if(s.zone!==p.zone){ s.zone=p.zone; s.x=p.x; s.y=p.y; s.orderPhase=null; }
  if(s.orderPhase==='charge'){
    if(s.orderTargetId){ const tgt=enemies[s.orderTargetId]; if(tgt && !tgt.dead){ s.orderX=tgt.x; s.orderY=tgt.y; } else { s.orderTargetId=null; } }
    s.chargeT=(s.chargeT||0)+dt;
    const d=Math.hypot(s.orderX-s.x,s.orderY-s.y);
    if(d>12 && s.chargeT<4){ s.x+=(s.orderX-s.x)/d*260*dt; s.y+=(s.orderY-s.y)/d*260*dt; summonSweep(s,id); }
    else { s.orderPhase='hold'; s.orderHoldT=s.orderHoldDurV||2.5; s.sweepHit=null; s.chargeT=0; fxEv('ring',s.x,s.y,45,0,0,45); }
  } else if(s.orderPhase==='hold'){
    s.orderHoldT-=dt;
    if(s.orderHoldT<=0){ s.orderPhase='return'; s.sweepHit=null; }
  } else if(s.orderPhase==='return'){
    const d=Math.hypot(p.x-s.x,p.y-s.y);
    if(d>35){ s.x+=(p.x-s.x)/d*260*dt; s.y+=(p.y-s.y)/d*260*dt; summonSweep(s,id); }
    else { s.orderPhase=null; }
  } else {
    const tx=p.x+p.fx*30, ty=p.y+p.fy*30;
    s.x+=(tx-s.x)*Math.min(1,dt*4); s.y+=(ty-s.y)*Math.min(1,dt*4);
  }
  const empowered=(s.orderPhase==='hold');
  const moving=(s.orderPhase==='charge'||s.orderPhase==='return');
  const willBuf=(p.commandStateT>0)?(p.commandStateSummonBuf||0):0;
  s.atkT=(s.atkT||0)-dt;
  if(s.atkT<=0 && !moving){
    s.atkT=(empowered?0.55:1.5)/(1+willBuf*0.5);
    const atkRange=empowered?250:170;
    let best=null,bd=atkRange;
    for(const eid in enemies){const e=enemies[eid];if(e.dead||e.zone!==s.zone)continue;if(!getStatus(e,'ravenmark'))continue;const d=Math.hypot(e.x-s.x,e.y-s.y);if(d<atkRange+60){best=e;bd=d;break;}}
    if(!best) for(const eid in enemies){const e=enemies[eid];if(e.dead||e.zone!==s.zone)continue;const d=Math.hypot(e.x-s.x,e.y-s.y);if(d<bd){bd=d;best=e;}}
    if(best){ const dmul=(empowered?1.6:1)*(getStatus(best,'ravenmark')?1.25:1)*(1+willBuf); hurtEnemy(best,s.atk*dmul,id); fxEv('swing',best.x,best.y,45,1,0,0); s.lastAtk=Date.now(); s.ax=best.x-s.x; s.ay=best.y-s.y; }
  }
}
function summonSweep(s,id){
  if(!s.sweepHit) s.sweepHit=new Set();
  for(const eid in enemies){const e=enemies[eid]; if(e.dead||e.zone!==s.zone)continue;
    if(s.sweepHit.has(eid))continue;
    if(Math.hypot(e.x-s.x,e.y-s.y)<(s.sweepRV||55)){
      hurtEnemy(e,s.sweepDmgV||14,id);
      s.sweepHit.add(eid);
      fxEv('swing',e.x,e.y,45,1,0,0);
    }
  }
}
function doFeedPet(p,id){
  if(!p.pet)return; const cost=30;
  if(p.gold<cost){ sendTo(id,{t:'toast',text:'Cần 30🪙 để cho Thú Cưng ăn'}); return; }
  p.gold-=cost; p.pet.fullness=100;
  p.pet.xp=(p.pet.xp||0)+15;
  while(p.pet.xp>=(p.pet.xpNext||40)){ p.pet.xp-=p.pet.xpNext; p.pet.lv++; p.pet.xpNext=Math.round((p.pet.xpNext||40)*1.3);
    const bs=petBaseStats(p.pet.lv); p.pet.atk=bs.atk; }
  sendTo(id,{t:'toast',text:'🍖 Thú Cưng no rồi, khỏe hơn hẳn!'}); sendInv(p,id);
}
const FUSION_DUR=300, FUSION_CD=900; // 5 phút hợp thể, 15 phút hồi chiêu (đặt ngắn để test — chỉnh dài hơn khi ưng ý)
function doFusion(p,id){
  if(!p.pet)return;
  if(p.fusedT>0){ sendTo(id,{t:'toast',text:'Đang hợp thể, chưa thể hủy giữa chừng.'}); return; }
  if((p.fusionCd||0)>0){ sendTo(id,{t:'toast',text:'Hợp thể còn hồi chiêu '+Math.ceil(p.fusionCd)+'s'}); return; }
  p.fusedT=FUSION_DUR; recompute(p);
  sendTo(id,{t:'toast',text:'⚡ Hợp thể với '+PET_TYPES.find(t=>t.id===p.pet.type).name+'! Sức mạnh tăng vọt trong '+FUSION_DUR+'s.'});
}
function doPermFusion(p,id){
  if(!p.pet)return;
  const bonus=Math.max(3,Math.round(p.pet.lv*0.8));
  p.STR+=bonus; p.VIT+=bonus; p.AGI+=bonus; p.INT+=bonus;
  const petName=PET_TYPES.find(t=>t.id===p.pet.type).name;
  p.pet=null; p.fusedT=0; p.fusionCd=0; recompute(p);
  sendTo(id,{t:'toast',text:'💫 '+petName+' đã hợp thể vĩnh viễn! +'+bonus+' mọi chỉ số mãi mãi.'});
  sendTo(id,{t:'skills',meta:skillMeta(p),passive:PASSIVES[p.cls],full:fullSkillList(p),loadout:p.loadout}); sendInv(p,id);
}
function doBuyHsPetEgg(p,id){
  if(p.hspet){ sendTo(id,{t:'toast',text:'Bạn đã có Thú Cưng rồi.'}); return; }
  if(p.lv<HSPET_MIN_LV){ sendTo(id,{t:'toast',text:'Cần đạt Lv '+HSPET_MIN_LV+' để mua trứng.'}); return; }
  if(p.zone!=='town'){ sendTo(id,{t:'toast',text:'Trứng Thú Cưng chỉ bán ở Thị Trấn An Bình.'}); return; }
  if(p.gold<HSPET_EGG_COST){ sendTo(id,{t:'toast',text:'Cần '+HSPET_EGG_COST+'🪙 để mua trứng.'}); return; }
  p.gold-=HSPET_EGG_COST;
  p.hspet={stat:{STR:0,VIT:0,AGI:0,INT:0},hunger:100};
  sendTo(id,{t:'toast',text:'🥚 Trứng nở rồi! Bạn có Thú Cưng mới.'}); sendInv(p,id); recompute(p);
}
function doFeedHsPet(p,id,itemId){
  if(!p.hspet)return;
  const idx=(p.inv||[]).findIndex(x=>x.id===itemId); if(idx<0)return;
  const it=p.inv[idx]; const stat=HSPET_FOOD_MAP[it.slot]; if(!stat)return;
  const gain=2+(it.tier||1)*2+(it.plus||0);
  p.inv.splice(idx,1); p.hspet.stat[stat]=(p.hspet.stat[stat]||0)+gain; p.hspet.hunger=100;
  recompute(p);
  sendTo(id,{t:'toast',text:'🍎 Thú Cưng ăn xong, +'+gain+' '+stat+' (đồng hành)!'});
  sendInv(p,id);
}
