function addEdge(L,zone){ var zd=ZONEDATA[zone]; if(!zd||!zd.w)return; var th=zd.theme||zone, E=EDGEP[th]||EDGEP.forest, pts=zd.portals||[];
  function nearP(x,y){ for(var i=0;i<pts.length;i++) if(Math.hypot(x-pts[i].x,y-pts[i].y)<pts[i].r+46)return true; return false; }
  var st=(th==='dungeon'||th==='tower'||th==='sanct')?96:62, i=0;
  for(var x=20;x<zd.w;x+=st){ i++; var j=h2(x,7)*18-9; if(!nearP(x,8)) L.push({t:'P:'+E[i%E.length],x:Math.round(x+j),y:6,edge:1}); if(!nearP(x,zd.h-6)) L.push({t:'P:'+E[(i+2)%E.length],x:Math.round(x-j),y:zd.h+12,edge:1}); }
  for(var y=60;y<zd.h;y+=st){ i++; var k=h2(3,y)*10; if(!nearP(6,y)) L.push({t:'P:'+E[i%E.length],x:Math.round(-4+k),y:y,edge:1}); if(!nearP(zd.w-6,y)) L.push({t:'P:'+E[(i+1)%E.length],x:Math.round(zd.w+4-k),y:y,edge:1}); }
  L.sort(function(a,b){return a.y-b.y;}); }
