function drawBA(key,cx,cy,hgt,fps,flip,once,t0){ var a=BA[key]; if(!a||!a.s.ready)return 0; var t=performance.now();
  var f=once?Math.min(a.n-1,Math.floor((t-t0)/(1000/fps))):Math.floor(t/(1000/fps))%a.n; var w=hgt*a.w/a.h;
  ctx.save(); ctx.translate(cx,0); if(flip)ctx.scale(-1,1); ctx.imageSmoothingEnabled=false;
  ctx.drawImage(a.s.img,f*a.w,0,a.w,a.h,Math.round(-w/2),Math.round(cy-hgt),Math.round(w),Math.round(hgt)); ctx.restore(); return hgt; }
