    for(var y2=0;y2<ny;y2++)for(var x2=0;x2<nx;x2++) T(pick(S.dirt,x2,y2),x2*32,y2*32);
    var pl=Z.plaza; if(pl){ for(var py=Math.floor(pl[1]/32);py<Math.ceil((pl[1]+pl[3])/32);py++)for(var px=Math.floor(pl[0]/32);px<Math.ceil((pl[0]+pl[2])/32);px++){
        var edge=(px===Math.floor(pl[0]/32)||py===Math.floor(pl[1]/32)||px===Math.ceil((pl[0]+pl[2])/32)-1||py===Math.ceil((pl[1]+pl[3])/32)-1); T(pick(edge?TT[(Z.pt||[])[1]||'green']:TT[(Z.pt||[])[0]||'beige'],px,py),px*32,py*32); } }
    // mẫu đỉnh (có cỏ hay không)
    var smp=[]; for(var sy=0;sy<=ny;sy++){ smp[sy]=[]; for(var sx=0;sx<=nx;sx++){ var wx=sx*32, wy=sy*32;
      var v=_vn(wx,wy,190)*0.75+_vn(wx+999,wy+333,64)*0.25, on=v>Z.thr;
      for(var k2=0;k2<segs.length&&on;k2++) if(_segD(wx,wy,segs[k2])<30) on=false;
      for(var k3=0;k3<pts.length&&on;k3++) if(Math.hypot(wx-pts[k3].x,wy-pts[k3].y)<pts[k3].r+20) on=false;
      if(pl&&on&&wx>pl[0]-8&&wx<pl[0]+pl[2]+8&&wy>pl[1]-8&&wy<pl[1]+pl[3]+8) on=false;
      smp[sy][sx]=on; } }
    (function(){ var F=[]; for(var a=0;a<=ny;a++){ F[a]=[]; for(var b=0;b<=nx;b++){ var wx=b*32, wy=a*32, f=false; for(var k=0;k<segs.length&&!f;k++) if(_segD(wx,wy,segs[k])<30) f=true; for(var k3=0;k3<pts.length&&!f;k3++) if(Math.hypot(wx-pts[k3].x,wy-pts[k3].y)<pts[k3].r+20) f=true; if(pl&&wx>pl[0]-8&&wx<pl[0]+pl[2]+8&&wy>pl[1]-8&&wy<pl[1]+pl[3]+8) f=true; F[a][b]=f; } }
      for(var pass=0;pass<2;pass++){ var N=[]; for(var a2=0;a2<=ny;a2++){ N[a2]=[]; for(var b2=0;b2<=nx;b2++){ var c=0; for(var dy=-1;dy<=1;dy++)for(var dx=-1;dx<=1;dx++){ var r=smp[a2+dy]; if(r&&r[b2+dx])c++; } N[a2][b2]=F[a2][b2]?false:(c>=5); } } smp=N; }
      for(var a3=0;a3<ny;a3++)for(var b3=0;b3<nx;b3++){ var m0=(smp[a3][b3]?8:0)+(smp[a3][b3+1]?4:0)+(smp[a3+1][b3]?2:0)+(smp[a3+1][b3+1]?1:0); if(m0===9||m0===6){ smp[a3][b3]=smp[a3][b3+1]=smp[a3+1][b3]=smp[a3+1][b3+1]=false; } } })();
