    function TB(m,X,Y){ var e=MAP[m]; g.drawImage(TERR,e[0][0]+e[1]*32,e[0][1]+e[2]*32,32,32,X,Y,32,32); }
    for(var cy=0;cy<ny;cy++)for(var cx=0;cx<nx;cx++){ var m=(smp[cy][cx]?8:0)+(smp[cy][cx+1]?4:0)+(smp[cy+1][cx]?2:0)+(smp[cy+1][cx+1]?1:0); if(!m)continue;
      var X=cx*32, Y=cy*32;
      if(m===15) T(pick(S.fill,cx,cy),X,Y); else if(m===9){ TB(8,X,Y); TB(1,X,Y); } else if(m===6){ TB(4,X,Y); TB(2,X,Y); } else TB(m,X,Y); }
    // điểm xuyết hoa / nấm / sỏi trên cỏ
