  if(Z.gray){ g.globalCompositeOperation='saturation'; g.globalAlpha=Z.gray; g.fillStyle='#808080'; g.fillRect(0,0,W,H); g.globalAlpha=1; }
  if(Z.tint){ g.globalCompositeOperation='multiply'; g.fillStyle=Z.tint[0]; g.globalAlpha=Z.tint[1]; g.fillRect(0,0,W,H); g.globalAlpha=1; }
  if((zd.floor||1)>1){ g.globalCompositeOperation='multiply'; g.fillStyle='rgb(40,30,50)'; g.globalAlpha=0.14*((zd.floor||1)-1); g.fillRect(0,0,W,H); g.globalAlpha=1; }
  g.globalCompositeOperation='source-over';
