var myQuests={defs:[],qk:{},qc:{},streak:0,checkedToday:false,nextReward:{gold:0,stones:0}}, qOpen=false;
function renderQuests(){
  var ck=document.getElementById('ckbox');
  var nr=myQuests.nextReward||{gold:0,stones:0};
  ck.innerHTML='<div class="cktitle">📅 Điểm danh · chuỗi '+(myQuests.streak||0)+' ngày</div>'+
    '<div class="ckreward">Hôm nay: +'+nr.gold+'🪙'+(nr.stones?(' +'+nr.stones+'🔨'):'')+'</div>'+
    '<button id="ckBtn" '+(myQuests.checkedToday?'disabled':'')+'>'+(myQuests.checkedToday?'Đã điểm danh':'Điểm danh ngay')+'</button>';
  var ckBtn=document.getElementById('ckBtn');
  if(!myQuests.checkedToday)ckBtn.addEventListener('pointerdown',function(ev){ev.preventDefault();ws.send(JSON.stringify({t:'checkin'}));});
  var ql=document.getElementById('qlist'); ql.innerHTML='';
  (myQuests.defs||[]).forEach(function(d){
    var val=(myQuests.qk&&myQuests.qk[d.id])||0, done=val>=d.target, claimed=myQuests.qc&&myQuests.qc[d.id];
    var row=document.createElement('div'); row.className='qrow';
    var rw=[]; if(d.reward.gold)rw.push('+'+d.reward.gold+'🪙'); if(d.reward.xp)rw.push('+'+d.reward.xp+'XP'); if(d.reward.stones)rw.push('+'+d.reward.stones+'🔨');
    row.innerHTML='<div class="qn">'+d.name+' · '+rw.join(' ')+'</div>'+
      '<div class="qbar"><i style="width:'+Math.min(100,val/d.target*100)+'%"></i></div>';
    var btn=document.createElement('button'); btn.textContent=claimed?'Đã nhận':(done?'Nhận thưởng':val+'/'+d.target);
    btn.disabled=claimed||!done;
    btn.addEventListener('pointerdown',function(ev){ev.preventDefault();ws.send(JSON.stringify({t:'claimquest',qid:d.id}));});
    row.appendChild(btn); ql.appendChild(row);
  });
  var el=document.getElementById('qdot'); if(el)updateQuestDot();
}
function updateQuestDot(){
  var anyReady=(!myQuests.checkedToday)|| (myQuests.defs||[]).some(function(d){return ((myQuests.qk&&myQuests.qk[d.id])||0)>=d.target && !(myQuests.qc&&myQuests.qc[d.id]);});
  document.getElementById('qdot').style.display=anyReady?'block':'none';
}
document.getElementById('qbtn').addEventListener('pointerdown',function(ev){ev.preventDefault();ev.stopPropagation();
  qOpen=!qOpen;document.getElementById('qPanel').style.display=qOpen?'flex':'none';if(qOpen)renderQuests();});
document.getElementById('qClose').addEventListener('pointerdown',function(ev){ev.preventDefault();
  qOpen=false;document.getElementById('qPanel').style.display='none';});
var SLOTICON={wpn:'⚔️',arm:'🛡️',hlm:'🪖',rng:'💍',glv:'🧤',boot:'🥾',neck:'📿',wing:'🪽'};
var SLOTNAME={wpn:'Vũ khí',arm:'Áo giáp',hlm:'Nón',rng:'Nhẫn',glv:'Găng',boot:'Giày',neck:'Dây chuyền',wing:'Cánh'};
var PAPERDOLL=['PET','hlm','wing', 'wpn','FIG','neck', 'glv','arm','boot', 'rng','MOUNT','DISC'];
var MAXPLUS=12, ENCH_RATE=[0.95,0.9,0.85,0.78,0.68,0.58,0.48,0.4,0.32,0.26,0.2,0.15];
function eRate(pl){return ENCH_RATE[pl]!==undefined?ENCH_RATE[pl]:0.12;}
function eCost(it){return it.tier*(((it.plus||0)+1))*10;}
function eStones(it){return it.tier+Math.floor((it.plus||0)/3);}
function eVal(it){return it.val+Math.round(it.val*(it.plus||0)*0.15);}
var ICON_ATLAS='data:image/png;base64,';
var ICON_COL={hlm:0,arm:1,glv:2,boot:3};
function iconCell(slot,tier){ var col=ICON_COL[slot]; if(col===undefined)return null; var row=Math.min(8,((tier||1)-1)*3);
  return 'width:38px;height:38px;background-image:url('+ICON_ATLAS+');background-size:228px 342px;background-position:-'+(col*38)+'px -'+(row*38)+'px;image-rendering:pixelated;'; }
function slotIcoHTML(slot,tier,op){ var st=iconCell(slot,tier); if(st) return '<div style="margin:auto;'+(op?'opacity:'+op+';':'')+st+'"></div>'; return '<span style="'+(op?'opacity:'+op:'')+'">'+SLOTICON[slot]+'</span>'; }
function itemPicHTML(it){ var ic=it.look?icoCSS(it.slot+':'+it.look,40):null; if(ic) return '<div style="margin:auto;'+ic+'"></div>';
  var u=it.look?itemPicURL(it.slot,it.look):null; return u?'<img src="'+u+'">':slotIcoHTML(it.slot,it.tier); }
var WINGFX={4:'#ff5a3a',5:'#ffe07a',7:'#7aff8a',6:'#c77dff',8:'#ff3a4a',9:'#ffc94a'};
var RARN=['Thường','Hiếm','Hoàn Hảo','Thần Khí'], RARC=['#d8d0c0','#6bb0ff','#5aff8a','#ffb347'];
var EXTXT={dmg:'+6% sát thương',hp:'+6% máu tối đa',mp:'+8% mana tối đa',gold:'+25% vàng nhặt',xp:'+10% kinh nghiệm'};
var MATN={chaos:'Ngọc Hỗn Nguyên',bless:'Ngọc Ước Nguyện',soul:'Ngọc Tâm Linh',feather:'Lông Vũ Thần Ưng',crest:'Tinh Hoa Phượng Hoàng'};
var MATK=['chaos','bless','soul','feather','crest'];
var myMats={}, chaosD=null, chaosOpen=false, chaosR='wing1', chaosSel=null, chaosBless=0, chaosBusy=false;
function rcls(it){ return (it.rar|0)>=1?(' r'+it.rar):(' t'+it.tier); }
function matHTML(k,n,px){ var c=icoCSS('mat:'+k,px||22); return '<span class="mt" title="'+MATN[k]+'"><span style="display:inline-block;'+(c||'')+'"></span>'+(n===undefined?'':('×'+n))+'</span>'; }
function renderMatBar(){ var b=document.getElementById('matBar'); if(!b)return; b.innerHTML=MATK.map(function(k){return matHTML(k,myMats[k]||0);}).join(''); }
function cRate(r,it,bless){ var b=0,pl=(it&&it.plus)||0,ra=(it&&it.rar)|0;
  if(r==='wing1')b=Math.min(70,20+pl*5+ra*10); else if(r==='wing2')b=Math.min(60,25+pl*5); else if(r==='wing3')b=Math.min(45,15+pl*4); else if(r==='refine')b=[55,35,18][ra]||0;
  return Math.min(85,b+Math.min(4,bless)*5); }
function cOk(r,it){ if(!it)return false; if(r==='wing1')return it.slot!=='wing'&&((it.plus||0)>=4||(it.rar|0)>=1); if(r==='wing2')return it.slot==='wing'&&(it.wl||it.tier)===1; if(r==='wing3')return it.slot==='wing'&&(it.wl||it.tier)===2; if(r==='refine')return it.slot!=='wing'&&(it.rar|0)<3; return false; }
function renderChaos(){ if(!chaosD)return; document.getElementById('chaosMats').innerHTML='<div id="matBarC" style="margin:0">'+MATK.map(function(k){return matHTML(k,myMats[k]||0);}).join('')+'</div>';
  var rc=document.getElementById('chaosRecs'); rc.innerHTML=''; chaosD.recipes.forEach(function(q){ var b=document.createElement('button'); b.textContent=q.n; if(q.id===chaosR){b.className='on'; document.getElementById('chaosDesc').textContent=q.desc;}
    b.addEventListener('pointerdown',function(ev){ev.preventDefault(); chaosR=q.id; chaosSel=null; renderChaos();}); rc.appendChild(b); });
  var all=myInv.slice(); for(var s in myEquip) if(myEquip[s]) all.push(myEquip[s]);
  var g=document.getElementById('chaosItems'); g.innerHTML=''; var any=false;
  all.forEach(function(it){ if(!cOk(chaosR,it))return; any=true; var c=document.createElement('div'); c.className='cell'+rcls(it)+(it.id===chaosSel?' sel':''); c.innerHTML=itemHTML(it);
    c.addEventListener('pointerdown',function(ev){ev.preventDefault(); chaosSel=it.id; renderChaos();}); g.appendChild(c); });
  if(!any) g.innerHTML='<div style="grid-column:1/-1;font-size:11px;color:#a08ab0;text-align:center">Không có đồ phù hợp công thức này</div>';
  var sel=null; all.forEach(function(it){ if(it.id===chaosSel)sel=it; });
  document.getElementById('cbN').textContent=chaosBless;
  document.getElementById('chaosRate').textContent=sel?(cRate(chaosR,sel,chaosBless)+'%'):'?';
  document.getElementById('chaosGo').disabled=!sel||chaosBusy||!chaosD.near;
  if(!chaosD.near) document.getElementById('chaosMsg').innerHTML='<span style="color:#ff9a8a">Phải đứng cạnh Goblin Hỗn Nguyên ở Thị Trấn</span>'; }
function chaosResult(m){ var ring=document.getElementById('chaosRing'), msg=document.getElementById('chaosMsg');
  if(m.rate===undefined){ msg.innerHTML='<span style="color:#ff9a8a">'+m.msg+'</span>'; chaosBusy=false; renderChaos(); return; }
  setTimeout(function(){ ring.classList.remove('spin'); chaosBusy=false; chaosSel=null;
    msg.innerHTML='<span style="color:'+(m.ok?'#5aff8a':'#ff6a5a')+';font-size:15px">'+(m.ok?'✨ ':'💥 ')+m.msg+'</span>'; renderChaos(); },1400); }
document.getElementById('chaosGo').addEventListener('pointerdown',function(ev){ev.preventDefault(); if(chaosBusy||!chaosSel)return; chaosBusy=true;
  document.getElementById('chaosRing').classList.add('spin'); document.getElementById('chaosMsg').textContent='Máy đang quay...'; document.getElementById('chaosGo').disabled=true;
  ws.send(JSON.stringify({t:'chaosmix',r:chaosR,itemId:chaosSel,bless:chaosBless})); });
document.getElementById('cbPlus').addEventListener('pointerdown',function(ev){ev.preventDefault(); chaosBless=Math.min(4,Math.min(chaosBless+1,myMats.bless||0)); renderChaos();});
document.getElementById('cbMinus').addEventListener('pointerdown',function(ev){ev.preventDefault(); chaosBless=Math.max(0,chaosBless-1); renderChaos();});
document.getElementById('chaosX').addEventListener('pointerdown',function(ev){ev.preventDefault(); chaosOpen=false; document.getElementById('chaosPanel').style.display='none';});
function itemHTML(it){var pl=it.plus||0;return itemPicHTML(it)+(pl>0?'<span class="pl">+'+pl+'</span>':'')+'<span class="v">'+eVal(it)+'</span>';}
function findMy(id){for(var i=0;i<myInv.length;i++)if(myInv[i].id===id)return{item:myInv[i],loc:'bag'};
  for(var s in myEquip){if(myEquip[s]&&myEquip[s].id===id)return{item:myEquip[s],loc:'equip',slot:s};}return null;}
