function drawOrb(id,v,mx,c1,c2){ var cv=document.getElementById(id); if(!cv)return; var g=cv.getContext('2d'), W=80, R=34, t=performance.now()/1000, r=Math.max(0,Math.min(1,v/(mx||1)));
  g.clearRect(0,0,W,W); g.save(); g.beginPath(); g.arc(40,42,R,0,7); g.clip(); g.fillStyle='#0a0606'; g.fillRect(0,0,W,W);
  var top=42+R-2*R*r; var gr=g.createLinearGradient(0,top,0,42+R); gr.addColorStop(0,c1); gr.addColorStop(1,c2); g.fillStyle=gr;
  g.beginPath(); g.moveTo(0,W); for(var x=0;x<=W;x+=4) g.lineTo(x,top+Math.sin(x/9+t*3)*2.2); g.lineTo(W,W); g.closePath(); g.fill();
  g.globalAlpha=0.35; g.fillStyle='#fff'; for(var i=0;i<4;i++){ var py=42+R-((t*18+i*17)%(2*R*r+1)); g.fillRect(24+i*9,py,2,2); } g.globalAlpha=1;
  var hl=g.createRadialGradient(30,28,2,40,42,R); hl.addColorStop(0,'rgba(255,255,255,0.35)'); hl.addColorStop(0.35,'rgba(255,255,255,0)'); g.fillStyle=hl; g.fillRect(0,0,W,W); g.restore();
  var ring=g.createLinearGradient(0,0,0,W); ring.addColorStop(0,'#ffe9a8'); ring.addColorStop(0.5,'#a8742a'); ring.addColorStop(1,'#5a3a12');
  g.lineWidth=5; g.strokeStyle=ring; g.beginPath(); g.arc(40,42,R+2,0,7); g.stroke(); g.lineWidth=1; g.strokeStyle='#2a1a08'; g.beginPath(); g.arc(40,42,R+4.5,0,7); g.stroke();
  for(var k=0;k<8;k++){ var a=k*Math.PI/4; g.fillStyle='#ffd76b'; g.fillRect(40+Math.cos(a)*(R+2)-1,42+Math.sin(a)*(R+2)-1,2,2); }
  g.font='bold 11px Trebuchet MS'; g.textAlign='center'; g.fillStyle='#fff'; g.shadowColor='#000'; g.shadowBlur=3; g.fillText(Math.ceil(Math.max(0,v)),40,46); }
(function(){ var c=document.createElement('canvas'); c.width=c.height=160; var g=c.getContext('2d'), d=g.createImageData(160,160);
  for(var i=0;i<d.data.length;i+=4){ var v=Math.random()*255|0; d.data[i]=d.data[i+1]=d.data[i+2]=v; d.data[i+3]=255; } g.putImageData(d,0,0);
  var el=document.getElementById('grain'); if(el){ el.style.backgroundImage='url('+c.toDataURL()+')'; } })();
var _mmT=0;
function drawMiniMap(){ var cv=document.getElementById('miniMap'); if(!cv)return; var now=performance.now(); if(now-_mmT<180)return; _mmT=now;
  var g=cv.getContext('2d'), zd=ZONEDATA[myZone]; if(!zd||!zd.w)return; var W=150,H=112, sx=W/zd.w, sy=H/zd.h; g.imageSmoothingEnabled=true;
  var B=GBAKE[myZone]; if(B) g.drawImage(B,0,0,zd.w,zd.h,0,0,W,H); else { g.fillStyle='#14100a'; g.fillRect(0,0,W,H); }
  g.fillStyle='rgba(0,0,0,0.25)'; g.fillRect(0,0,W,H);
  (zd.houses||[]).forEach(function(h){ g.fillStyle='#8a4a2a'; g.fillRect((h.x-h.w/2)*sx,(h.y-h.w*0.8)*sy,h.w*sx,h.w*0.8*sy); });
  (zd.portals||[]).forEach(function(p){ g.fillStyle='#ffd76b'; g.beginPath(); g.arc(p.x*sx,p.y*sy,3.5,0,7); g.fill(); });
  for(var i=0;i<NPCLIST.length;i++){ var n=NPCLIST[i]; if(n.zone!==myZone)continue; g.fillStyle='#6bff8a'; g.fillRect(n.x*sx-2,n.y*sy-2,4,4); }
  for(var e in enemies){ var en=enemies[e]; if(!en||en.dead)continue; if(en.boss){ g.fillStyle=(Math.floor(now/300)%2)?'#ff3a3a':'#ffb0b0'; g.beginPath(); g.arc(en.x*sx,en.y*sy,4,0,7); g.fill(); } else { g.fillStyle='rgba(255,90,70,0.7)'; g.fillRect(en.x*sx-1,en.y*sy-1,2,2); } }
  for(var pid in players){ var pp=players[pid]; if(pp.zone!==myZone||pid==myId)continue; g.fillStyle='#9fd0ff'; g.fillRect(pp.x*sx-1.5,pp.y*sy-1.5,3,3); }
  var me=players[myId]; if(me){ var mx=(myPX!==null?myPX:me.x)*sx, my=(myPY!==null?myPY:me.y)*sy; g.fillStyle='#fff'; g.strokeStyle='#ffd76b'; g.lineWidth=2; g.beginPath(); g.arc(mx,my,3.5,0,7); g.fill(); g.stroke(); }
  g.strokeStyle='#ffe9a8'; g.lineWidth=1; g.strokeRect(0.5,0.5,W-1,H-1); }
function setBar(bi,ti,v,mx){var el=document.getElementById(bi);if(el){el.style.width=Math.max(0,v/mx*100)+'%';document.getElementById(ti).textContent=Math.ceil(Math.max(0,v))+'/'+mx;}}

