const CLIENT_GZ = zlib.gzipSync(Buffer.from(CLIENT_PAGE,'utf8'),{level:9});
const CLIENT_ETAG = '"'+require('crypto').createHash('md5').update(CLIENT_PAGE).digest('hex').slice(0,16)+'"';
const server = http.createServer((req,res)=>{
  if(req.url==='/credits'){ res.writeHead(200,{'Content-Type':'text/html; charset=utf-8','Cache-Control':'public, max-age=86400'}); return res.end(CREDITS_HTML); }
  const am=/^\/a\/([0-9a-f]{12})\.(png|jpg)$/.exec(req.url||'');
  if(am){ const A=ASSETS[am[1]]; if(!A){ res.writeHead(404); return res.end(); }
    res.writeHead(200,{'Content-Type':A.type,'Cache-Control':'public, max-age=31536000, immutable','Content-Length':A.buf.length}); return res.end(A.buf); }
  const h={ 'Content-Type':'text/html; charset=utf-8', 'Cache-Control':'no-cache', 'ETag':CLIENT_ETAG, 'Vary':'Accept-Encoding' };
  if(req.headers['if-none-match']===CLIENT_ETAG){ res.writeHead(304,h); return res.end(); }
  if(/gzip/.test(req.headers['accept-encoding']||'')){ h['Content-Encoding']='gzip'; res.writeHead(200,h); return res.end(CLIENT_GZ); }
  res.writeHead(200,h); res.end(CLIENT_PAGE);
});
const wss = new WebSocketServer({ server, perMessageDeflate:{ threshold:256, zlibDeflateOptions:{level:3}, serverNoContextTakeover:false, clientNoContextTakeover:true } }); // v3.23: nén gói tin → giảm băng thông ~5-8 lần
wss.on('error', (err) => { console.error('⚠️ Lỗi WebSocketServer (đã chặn):', err && err.message); });

