  orbs(e,tp,T){ bcastSk(e,'orbs',0.8); const rings=(T>=6||e.enraged)?4:3, per=10; let t=0; const off=Math.random()*6.283;
    for(let r=1;r<=rings;r++) for(let k=0;k<per;k++){ const a=off+k*6.283/per+(r%2?0.31:0); t=hz(e,{x:e.x+Math.cos(a)*r*105,y:e.y+Math.sin(a)*r*105,R:40,st:2},0.8+r*0.32,0.85); } return t; }
