// bộ đòn + combo riêng từng boss
const BOSS_KIT={
  taur:{sk:['slam','charge','wave','leap'],combo:['charge','charge','slam']},
  jelly:{sk:['rain','ring','orbs','cross'],combo:['vortex','ring']},
  daddy:{sk:['breath','rain','vortex','slam'],combo:['breath','rain','breath']},
  phoenix:{sk:['breath','rain','cross','leap'],combo:['leap','cross','rain']},
  maw:{sk:['summon','orbs','safe','blink'],combo:['summon','orbs','orbs']},
  'h:b_minoking':{sk:['charge','wave','slam','leap','ring'],combo:['leap','wave','charge']},
  'h:b_skelking':{sk:['summon','cross','safe','rain','shield'],combo:['cross','cross','summon']},
  lava:{sk:['charge','breath','wave','slam','safe'],combo:['charge','charge','wave']},
  'h:b_archangel':{sk:['rain','cross','safe','blink','orbs','shield'],combo:['blink','cross','safe']},
  psycho:{sk:['charge','blink','vortex','slam'],combo:['blink','charge','blink']}
};
function runCombo(e,tp,list){ let t=0; list.forEach((k,i)=>{ setTimeout(()=>{ if(e.dead)return; let tgt=tp; const L=plist(e,700); if(L.length) tgt=L[Math.floor(Math.random()*L.length)]; BSK[k](e,tgt,ztier(e.zone)); },t*1000); t+=(k==='summon'?1.4:(k==='safe'?2.6:1.25)); }); return t; }
function bossPattern(e,tp){ const r=Math.random(), en=e.enraged?1:0;
  if(r<0.34){ bossTele(e,[{x:e.x,y:e.y}],180+en*50,1.3,1.4,0,1); e.castT=1.3; }
  else if(r<0.68){ const pts=[]; for(const pid in players){ const p=players[pid]; if(!p.chosen||p.dead||p.zone!==e.zone)continue; if(Math.hypot(p.x-e.x,p.y-e.y)<650) pts.push({x:p.x,y:p.y}); }
    for(let k=0;k<2+en*3;k++) pts.push({x:tp.x+(Math.random()-0.5)*280,y:tp.y+(Math.random()-0.5)*280}); bossTele(e,pts,68,1.0,1.0,25,2); e.castT=0.8; }
  else { const a=Math.atan2(tp.y-e.y,tp.x-e.x), pts=[]; for(let k=1;k<=7;k++) pts.push({x:e.x+Math.cos(a)*k*58,y:e.y+Math.sin(a)*k*58}); bossTele(e,pts,52,0.9,1.15,0,3);
    setTimeout(()=>{ if(!e.dead){ e.dashT=0.4; e.dashVX=Math.cos(a)*1000; e.dashVY=Math.sin(a)*1000; e.dashHit=false; CURZ=e.zone; fxEv('bdash',e.x,e.y,bossEl(e),Math.cos(a),Math.sin(a),400); } },900); e.castT=0.9; } }
function bossRewards(e){ const by=e.dmgBy||{}; const zt=ztier(e.zone); const names=[];
  for(const pid in by){ const p=players[pid]; if(!p||!p.chosen||by[pid]<e.maxhp*0.04)continue;
    if(!p.cum)p.cum={}; p.cum['boss_'+e.zone]=(p.cum['boss_'+e.zone]||0)+1;
    const nItems=1+(zt>=6?1:0)+(zt>=10?1:0)+(e.enraged?0:0);
    let it=null; for(let q=0;q<nItems;q++){ it=makeItem(Math.min(3,itemTierFor(zt)+(Math.random()<0.3?1:0)),Math.max(q===0&&zt>=8?2:1,rollRar('boss',zt))); it.ilv=zt; it.val=Math.round(it.val*(1+0.2*(zt-1))); if(p.inv.length<24){ p.inv.push(it); } }
    if(zt>=5){ p.mats=p.mats||{}; p.mats.chaos=(p.mats.chaos||0)+1+Math.floor(zt/5); p.mats.soul=(p.mats.soul||0)+Math.floor(zt/4); } const g=Math.round((e.gold||200)*0.6); p.gold+=g; dropMats(p,+pid,e);
    sendTo(+pid,{t:'toast',text:'🎁 Phần thưởng góp sức hạ '+(e.mname||'Boss')+': '+itemLabel(it)+' + '+g+'🪙'}); sendInv(p,+pid); names.push(p.charDisplayName||('#'+pid)); }
  if(names.length) bcast({t:'toast',text:'⚔️ '+(e.mname||'Boss')+' đã gục trước: '+names.slice(0,6).join(', ')}); }
function bossSkill(e,tp){
  if(!e.enraged && e.hp<e.maxhp*0.5){ e.enraged=true; e.spd=Math.round(e.spd*1.35); e.dmg=Math.round(e.dmg*1.2); CURZ=e.zone; fxEv('bimp',e.x,e.y,0,4,bossEl(e),170);
    for(const pid in players){ const p=players[pid]; if(p.chosen&&p.zone===e.zone) sendTo(+pid,{t:'toast',text:'⚠️ '+(e.mname||'Boss')+' NỔI ĐIÊN! Đòn đánh nhanh và đau hơn!'}); } }
  const T=ztier(e.zone), kit=BOSS_KIT[e.bk]||{sk:['slam','rain','charge'],combo:['rain','slam']};
  const cd=Math.max(2.4,(6.2-T*0.22)*(e.enraged?0.72:1));
  if(Math.random()<(e.enraged?0.42:0.22)+T*0.01){ const t=runCombo(e,tp,kit.combo); e.skT=t+cd; return; }
  let k=kit.sk[Math.floor(Math.random()*kit.sk.length)]; if(k===e._lastSk) k=kit.sk[(kit.sk.indexOf(k)+1)%kit.sk.length]; e._lastSk=k;
  const t=BSK[k](e,tp,T)||1; e.skT=t+cd; }
// ---- BOSS LANG THANG (Gã Điên Mặt Nạ): 30 phút xuất hiện 1 lần ở vùng ngẫu nhiên, đi khắp map, lao húc
const ROAM={phase:'countdown',t:1500,eid:null,zone:null};
function tickRoam(dt){ ROAM.t-=dt;
  if(ROAM.phase==='countdown'&&ROAM.t<=0){ const zs=COMBAT_ZONES.filter(q=>!/^dungeon/.test(q)); const z=zs[Math.floor(Math.random()*zs.length)]; const Z=ZONES[z];
    const id=nextE++; const tier=Math.max(3,Z.tier||1); const x=Z.w/2+(Math.random()-0.5)*300, y=Z.h/2+(Math.random()-0.5)*200;
    ROAM.n=(ROAM.n||0)+1; const lava=(ROAM.n%2===0); const nm=lava?'Kỵ Sĩ Dung Nham':'Gã Điên Mặt Nạ';
    enemies[id]={x,y,zone:z,hp:(lava?3200:2600)*tier,maxhp:(lava?3200:2600)*tier,spd:lava?80:70,atk:0,dead:false,respawnT:0,xp:900*tier,gold:320*tier,r:34,boss:true,dmg:(lava?36:32)*tier,lairX:x,lairY:y,leash:1400,bk:lava?'lava':'psycho',mname:nm,skT:4,roam:true};
    ROAM.eid=id; ROAM.zone=z; ROAM.phase='active'; ROAM.t=1200; ROAM.name=nm;
    bcast({t:'bossbanner',name:nm,zone:Z.name}); bcast({t:'toast',text:(lava?'🔥 ':'💢 ')+nm+' đang lang thang ở '+Z.name+'!'}); }
  else if(ROAM.phase==='active'){ const e=enemies[ROAM.eid];
    if(!e||e.dead){ ROAM.phase='countdown'; ROAM.t=1800; ROAM.eid=null; }
    else if(ROAM.t<=0){ delete enemies[ROAM.eid]; ROAM.phase='countdown'; ROAM.t=1800; ROAM.eid=null; bcast({t:'toast',text:(ROAM.name||'Boss')+' đã bỏ đi...'}); } } }
